Save the following as **`tram-junction.html`** and open it in a modern browser. It uses only the Three.js core ES module from cdnjs; all geometry, animation, signals, and camera controls are generated in the file.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Tram-Priority Pedestrian Scramble Junction</title>

  <style>
    :root {
      color-scheme: dark;
      --panel: rgba(13, 22, 31, 0.84);
      --border: rgba(255, 255, 255, 0.14);
      --text: #f4f7fb;
      --muted: #9fb0c0;
      --green: #58e6a3;
      --amber: #ffc857;
      --red: #ff6577;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #91a9bc;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system,
        BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    #app,
    #app canvas {
      width: 100%;
      height: 100%;
      display: block;
    }

    #app canvas {
      touch-action: none;
      cursor: grab;
    }

    #app canvas:active {
      cursor: grabbing;
    }

    .panel {
      position: fixed;
      z-index: 10;
      top: 20px;
      left: 20px;
      width: min(370px, calc(100vw - 40px));
      padding: 18px 19px 16px;
      color: var(--text);
      background: var(--panel);
      border: 1px solid var(--border);
      border-radius: 16px;
      box-shadow: 0 18px 50px rgba(0, 0, 0, 0.25);
      backdrop-filter: blur(14px);
      -webkit-backdrop-filter: blur(14px);
      user-select: none;
    }

    .eyebrow {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 7px;
      color: var(--green);
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 0.16em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--green);
      box-shadow: 0 0 14px rgba(88, 230, 163, 0.8);
    }

    h1 {
      margin: 0;
      font-size: clamp(20px, 3vw, 28px);
      line-height: 1.08;
      letter-spacing: -0.035em;
    }

    .subtitle {
      margin: 8px 0 15px;
      color: var(--muted);
      font-size: 13px;
      line-height: 1.45;
    }

    .phase {
      min-height: 54px;
      padding: 11px 12px;
      background: rgba(255, 255, 255, 0.055);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 10px;
    }

    #phase-title {
      font-size: 15px;
      font-weight: 800;
    }

    #phase-description {
      margin-top: 4px;
      color: var(--muted);
      font-size: 11px;
      line-height: 1.4;
    }

    .progress {
      height: 4px;
      margin-top: 14px;
      overflow: hidden;
      background: rgba(255, 255, 255, 0.09);
      border-radius: 999px;
    }

    #progress-fill {
      width: 0;
      height: 100%;
      background: linear-gradient(90deg, #58e6a3, #9bf5cf);
      border-radius: inherit;
    }

    .stats {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 8px;
      margin-top: 13px;
    }

    .stat {
      padding: 9px 10px;
      background: rgba(255, 255, 255, 0.045);
      border: 1px solid rgba(255, 255, 255, 0.07);
      border-radius: 9px;
    }

    .stat-label {
      color: var(--muted);
      font-size: 9px;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .stat-value {
      margin-top: 3px;
      font-size: 14px;
      font-weight: 750;
    }

    .legend {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      margin-top: 14px;
      color: var(--muted);
      font-size: 10px;
    }

    .legend span {
      display: inline-flex;
      align-items: center;
      gap: 6px;
    }

    .swatch {
      width: 9px;
      height: 9px;
      border-radius: 50%;
    }

    .help {
      position: fixed;
      z-index: 10;
      right: 18px;
      bottom: 16px;
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 10px 12px;
      color: rgba(255, 255, 255, 0.82);
      background: rgba(13, 22, 31, 0.72);
      border: 1px solid rgba(255, 255, 255, 0.12);
      border-radius: 11px;
      font-size: 11px;
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
      user-select: none;
    }

    .help b {
      color: #fff;
    }

    button {
      padding: 7px 10px;
      color: #17212b;
      background: #f4f7fb;
      border: 0;
      border-radius: 7px;
      font: inherit;
      font-size: 10px;
      font-weight: 800;
      cursor: pointer;
    }

    button:hover {
      background: #ffffff;
    }

    #loading {
      position: fixed;
      z-index: 30;
      inset: 0;
      display: grid;
      place-items: center;
      color: white;
      background: #14212b;
      transition: opacity 0.45s ease;
    }

    #loading.hidden {
      opacity: 0;
      pointer-events: none;
    }

    .loader {
      text-align: center;
    }

    .loader-ring {
      width: 42px;
      height: 42px;
      margin: 0 auto 14px;
      border: 3px solid rgba(255, 255, 255, 0.15);
      border-top-color: #58e6a3;
      border-radius: 50%;
      animation: spin 0.8s linear infinite;
    }

    .loader p {
      margin: 0;
      font-size: 12px;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    @keyframes spin {
      to {
        transform: rotate(360deg);
      }
    }

    @media (max-width: 620px) {
      .panel {
        top: 12px;
        left: 12px;
        width: min(350px, calc(100vw - 24px));
        padding: 14px;
      }

      .subtitle {
        margin-bottom: 10px;
      }

      .phase {
        min-height: 47px;
        padding: 8px 9px;
      }

      #phase-description {
        display: none;
      }

      .stats {
        margin-top: 9px;
      }

      .legend {
        margin-top: 9px;
      }

      .help {
        right: 10px;
        bottom: 10px;
      }

      .help .desktop-help {
        display: none;
      }
    }
  </style>
</head>

<body>
  <div id="app"></div>

  <section class="panel">
    <div class="eyebrow">Live intersection study</div>
    <h1>Tram-Priority<br>Scramble Junction</h1>
    <p class="subtitle">
      Pedestrians cross only when the tram is clear. When the junction opens,
      walkers use all four approaches at once.
    </p>

    <div class="phase">
      <div id="phase-title">Tram approaching</div>
      <div id="phase-description">
        The tram holds the right of way and all pedestrian crossings are red.
      </div>
    </div>

    <div class="progress">
      <div id="progress-fill"></div>
    </div>

    <div class="stats">
      <div class="stat">
        <div class="stat-label">Tram position</div>
        <div class="stat-value" id="tram-position">−38.0 m</div>
      </div>
      <div class="stat">
        <div class="stat-label">Active crossings</div>
        <div class="stat-value" id="crossing-count">0</div>
      </div>
    </div>

    <div class="legend">
      <span><i class="swatch" style="background:#ffc857"></i>Tram priority</span>
      <span><i class="swatch" style="background:#58e6a3"></i>Pedestrians</span>
      <span><i class="swatch" style="background:#ff6577"></i>Vehicle signals</span>
    </div>
  </section>

  <div class="help">
    <span><b>Drag</b> to orbit</span>
    <span><b>Scroll</b> to zoom</span>
    <span class="desktop-help"><b>R</b> reset view</span>
    <button id="reset-view" type="button">Reset view</button>
  </div>

  <div id="loading">
    <div class="loader">
      <div class="loader-ring"></div>
      <p>Building intersection</p>
    </div>
  </div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer and scene
    // -------------------------------------------------------------------------

    const app = document.getElementById("app");

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.08;
    renderer.domElement.setAttribute(
      "aria-label",
      "Interactive three-dimensional tram priority junction"
    );
    app.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x9db6c5);
    scene.fog = new THREE.Fog(0x9db6c5, 48, 115);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.1,
      180
    );

    const hemi = new THREE.HemisphereLight(0xdceeff, 0x59635b, 2.1);
    scene.add(hemi);

    const sun = new THREE.DirectionalLight(0xfff0d2, 3.2);
    sun.position.set(-22, 34, 18);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -42;
    sun.shadow.camera.right = 42;
    sun.shadow.camera.top = 42;
    sun.shadow.camera.bottom = -42;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 95;
    sun.shadow.bias = -0.00035;
    scene.add(sun);

    const fill = new THREE.DirectionalLight(0xa8d6ff, 0.8);
    fill.position.set(25, 12, -20);
    scene.add(fill);

    // -------------------------------------------------------------------------
    // Materials and geometry helpers
    // -------------------------------------------------------------------------

    const materials = {
      ground: new THREE.MeshStandardMaterial({
        color: 0x7f8c79,
        roughness: 0.95
      }),
      asphalt: new THREE.MeshStandardMaterial({
        color: 0x293238,
        roughness: 0.93
      }),
      sidewalk: new THREE.MeshStandardMaterial({
        color: 0xa7aaa3,
        roughness: 0.9
      }),
      curb: new THREE.MeshStandardMaterial({
        color: 0xd0cbc0,
        roughness: 0.85
      }),
      marking: new THREE.MeshStandardMaterial({
        color: 0xe9e7d8,
        roughness: 0.75
      }),
      yellow: new THREE.MeshStandardMaterial({
        color: 0xf4c54e,
        roughness: 0.7
      }),
      building: new THREE.MeshStandardMaterial({
        color: 0x87939a,
        roughness: 0.85
      }),
      roof: new THREE.MeshStandardMaterial({
        color: 0x53616a,
        roughness: 0.8
      }),
      dark: new THREE.MeshStandardMaterial({
        color: 0x26323a,
        roughness: 0.65
      }),
      glass: new THREE.MeshStandardMaterial({
        color: 0x183647,
        emissive: 0x102c3b,
        emissiveIntensity: 0.45,
        roughness: 0.25,
        metalness: 0.25
      }),
      tram: new THREE.MeshStandardMaterial({
        color: 0x176b83,
        roughness: 0.38,
        metalness: 0.38
      }),
      tramLight: new THREE.MeshStandardMaterial({
        color: 0xfff4c7,
        emissive: 0xffd77a,
        emissiveIntensity: 1.7
      }),
      headlight: new THREE.MeshStandardMaterial({
        color: 0xffffff,
        emissive: 0xd9f5ff,
        emissiveIntensity: 2.2
      }),
      trunk: new THREE.MeshStandardMaterial({
        color: 0x69513b,
        roughness: 1
      }),
      foliage: new THREE.MeshStandardMaterial({
        color: 0x426c4d,
        roughness: 0.95
      }),
      lamp: new THREE.MeshStandardMaterial({
        color: 0xffe6a6,
        emissive: 0xffc55c,
        emissiveIntensity: 0.75
      })
    };

    function box(
      parent,
      width,
      height,
      depth,
      x,
      y,
      z,
      material,
      castShadow = true,
      receiveShadow = true
    ) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(width, height, depth),
        material
      );
      mesh.position.set(x, y, z);
      mesh.castShadow = castShadow;
      mesh.receiveShadow = receiveShadow;
      parent.add(mesh);
      return mesh;
    }

    function cylinder(
      parent,
      radiusTop,
      radiusBottom,
      height,
      x,
      y,
      z,
      material,
      segments = 12
    ) {
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(
          radiusTop,
          radiusBottom,
          height,
          segments
        ),
        material
      );
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function sphere(parent, radius, x, y, z, material, segments = 12) {
      const mesh = new THREE.Mesh(
        new THREE.SphereGeometry(radius, segments, Math.max(6, segments / 2)),
        material
      );
      mesh.position.set(x, y, z);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    // -------------------------------------------------------------------------
    // Street, crosswalks, lane markings, and signals
    // -------------------------------------------------------------------------

    box(scene, 100, 0.3, 100, 0, -0.25, 0, materials.ground, false, true);
    box(scene, 34, 0.12, 34, 0, 0, 0, materials.asphalt, false, true);

    // Four raised sidewalks.
    box(scene, 34, 0.34, 6, 0, 0.17, 20, materials.sidewalk);
    box(scene, 34, 0.34, 6, 0, 0.17, -20, materials.sidewalk);
    box(scene, 6, 0.34, 34, 20, 0.17, 0, materials.sidewalk);
    box(scene, 6, 0.34, 34, -20, 0.17, 0, materials.sidewalk);

    // Curb edges.
    box(scene, 34, 0.22, 0.25, 0, 0.31, 17, materials.curb);
    box(scene, 34, 0.22, 0.25, 0, 0.31, -17, materials.curb);
    box(scene, 0.25, 0.22, 34, 17, 0.31, 0, materials.curb);
    box(scene, 0.25, 0.22, 34, -17, 0.31, 0, materials.curb);

    // Dashed lane dividers.
    for (const z of [-6.5, 6.5]) {
      for (let x = -15; x <= 15; x += 3.2) {
        box(scene, 2.65, 0.055, 0.12, x, 0.08, z, materials.marking, false);
      }
    }

    for (const x of [-6.5, 6.5]) {
      for (let z = -15; z <= 15; z += 3.2) {
        box(scene, 0.12, 0.055, 2.65, x, 0.08, z, materials.marking, false);
      }
    }

    // Zebra crossings.
    for (let z = -5.4; z <= 5.4; z += 1.35) {
      box(scene, 2.15, 0.055, 0.55, 0, 0.1, z, materials.marking, false);
    }

    for (let x = -5.4; x <= 5.4; x += 1.35) {
      box(scene, 0.55, 0.055, 2.15, x, 0.1, 0, materials.marking, false);
    }

    // Stop lines.
    for (const z of [-8.7, 8.7]) {
      box(scene, 13.5, 0.06, 0.35, 0, 0.1, z, materials.marking, false);
    }

    for (const x of [-8.7, 8.7]) {
      box(scene, 0.35, 0.06, 13.5, x, 0.1, 0, materials.marking, false);
    }

    // Tram rails and sleepers.
    for (const x of [-1.2, 1.2]) {
      box(scene, 0.12, 0.13, 76, x, 0.16, 0, materials.dark, false);
    }

    for (let z = -38; z <= 38; z += 2.4) {
      box(scene, 3.25, 0.12, 0.28, 0, 0.1, z, materials.dark, false);
    }

    // -------------------------------------------------------------------------
    // Signal construction
    // -------------------------------------------------------------------------

    function makeSignal(x, z, rotation = 0, pedestrian = false) {
      const group = new THREE.Group();
      group.position.set(x, 0, z);
      group.rotation.y = rotation;
      scene.add(group);

      cylinder(group, 0.075, 0.09, 3.2, 0, 1.6, 0, materials.dark, 10);

      const housing = new THREE.Group();
      housing.position.y = 2.75;
      housing.rotation.y = rotation;
      group.add(housing);

      box(housing, 0.68, 1.15, 0.38, 0, 0, 0, materials.dark);

      const red = new THREE.MeshStandardMaterial({
        color: 0x5a1720,
        emissive: 0xff2843,
        emissiveIntensity: 0.15
      });

      const amber = new THREE.MeshStandardMaterial({
        color: 0x7a5115,
        emissive: 0xffb52e,
        emissiveIntensity: 0.15
      });

      const green = new THREE.MeshStandardMaterial({
        color: 0x153c2b,
        emissive: 0x36e989,
        emissiveIntensity: 0.15
      });

      const redLight = new THREE.Mesh(
        new THREE.CircleGeometry(0.17, 18),
        red
      );
      redLight.position.set(0, 0.34, 0.2);
      housing.add(redLight);

      const amberLight = new THREE.Mesh(
        new THREE.CircleGeometry(0.17, 18),
        amber
      );
      amberLight.position.set(0, 0.02, 0.205);
      housing.add(amberLight);

      const greenLight = new THREE.Mesh(
        new THREE.CircleGeometry(0.17, 18),
        green
      );
      greenLight.position.set(0, -0.34, 0.2);
      housing.add(greenLight);

      const signal = {
        group,
        housing,
        redLight,
        amberLight,
        greenLight,
        red,
        amber,
        green
      };

      return signal;
    }

    function updateSignal(signal, state) {
      const redOn = state.red;
      const amberOn = state.amber;
      const greenOn = state.green;

      signal.redLight.material.emissiveIntensity = redOn ? 2.4 : 0.12;
      signal.amberLight.material.emissiveIntensity = amberOn ? 2.4 : 0.12;
      signal.greenLight.material.emissiveIntensity = greenOn ? 2.4 : 0.12;
    }

    const pedestrianSignals = [
      makeSignal(8, 8),
      makeSignal(-8, 8),
      makeSignal(8, -8),
      makeSignal(-8, -8)
    ];

    const vehicleSignals = [
      makeSignal(0, -9, Math.PI, true),
      makeSignal(0, 9, Math.PI, true),
      makeSignal(9, 0, Math.PI / 2, true),
      makeSignal(-9, 0, Math.PI / 2, true)
    ];

    const tramSignal = makeSignal(4, -18, 0, false);

    // -------------------------------------------------------------------------
    // Buildings, trees, lamps, and street signage
    // -------------------------------------------------------------------------

    function makeBuilding(x, z, width, depth, height, color) {
      const group = new THREE.Group();
      group.position.set(x, 0.3, z);
      scene.add(group);

      const bodyMaterial = new THREE.MeshStandardMaterial({
        color,
        roughness: 0.86
      });

      box(group, width, height, depth, 0, height / 2, 0, bodyMaterial);
      box(group, width + 0.35, 0.28, depth + 0.35, 0, height + 0.1, 0, materials.roof);
      box(group, width * 0.28, 0.55, depth * 0.28, 0, height + 0.5, 0, materials.dark);

      const windowMaterial = new THREE.MeshStandardMaterial({
        color: 0xffddb0,
        emissive: 0xffa84d,
        emissiveIntensity: 0.48,
        roughness: 0.4
      });

      const columns = Math.max(2, Math.floor(width / 2.4));
      const rows = Math.max(2, Math.floor(height / 2.2));

      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < columns; col++) {
          const wx = -width / 2 + 1.2 + col * ((width - 2.4) / Math.max(1, columns - 1));
          const wy = 1.25 + row * 1.45;

          box(group, 1.05, 1.25, 0.08, wx, wy, -depth / 2 - 0.05, windowMaterial, false);
          box(group, 1.05, 1.25, 0.08, wx, wy, depth / 2 + 0.05, windowMaterial, false);
          box(group, 0.08, 1.25, 1.05, width / 2 + 0.05, wy, wx, windowMaterial, false);
          box(group, 0.08, 1.25, 1.05, -width / 2 - 0.05, wy, wx, windowMaterial, false);
        }
      }
    }

    makeBuilding(-10, -27, 8, 6, 7, 0x9ca6a8);
    makeBuilding(4, -28, 10, 7, 8, 0x71838a);
    makeBuilding(-10, 27, 8, 6, 6, 0x87939a);
    makeBuilding(4, 28, 10, 7, 9, 0xa3aaa6);
    makeBuilding(-27, -7, 6, 8, 6, 0x73838a);
    makeBuilding(-27, 12, 7, 6, 7, 0x919a9b);
    makeBuilding(27, -7, 8, 6, 7, 0x667b85);
    makeBuilding(27, 12, 7, 6, 5, 0x8b8e8a);

    function makeTree(x, z, scale = 1) {
      const group = new THREE.Group();
      group.position.set(x, 0.3, z);
      group.scale.setScalar(scale);
      scene.add(group);

      cylinder(group, 0.12, 0.18, 2.1, 0, 1.05, 0, materials.trunk, 8);

      const crown = new THREE.Mesh(
        new THREE.IcosahedronGeometry(1.15, 1),
        materials.foliage
      );
      crown.position.y = 2.65;
      crown.scale.y = 1.2;
      crown.castShadow = true;
      crown.receiveShadow = true;
      group.add(crown);

      const crown2 = new THREE.Mesh(
        new THREE.IcosahedronGeometry(0.8, 1),
        materials.foliage
      );
      crown2.position.set(0.65, 2.25, 0.15);
      crown2.castShadow = true;
      group.add(crown2);
    }

    makeTree(-24, 23, 1.05);
    makeTree(24, 23, 0.95);
    makeTree(-24, -23, 1.0);
    makeTree(24, -23, 0.9);
    makeTree(-15, 14, 0.75);
    makeTree(15, -14, 0.75);

    function makeLamp(x, z) {
      const group = new THREE.Group();
      group.position.set(x, 0.3, z);
      scene.add(group);

      cylinder(group, 0.065, 0.09, 4.2, 0, 2.1, 0, materials.dark, 10);
      box(group, 1.25, 0.08, 0.08, 0.5, 4.15, 0, materials.dark);
      box(group, 0.75, 0.13, 0.28, 1.02, 4.05, 0, materials.dark);
      box(group, 0.58, 0.05, 0.2, 1.02, 3.94, 0, materials.lamp, false);
    }

    makeLamp(-14, 14);
    makeLamp(14, 14);
    makeLamp(-14, -14);
    makeLamp(14, -14);

    // Tram priority sign.
    const signCanvas = document.createElement("canvas");
    signCanvas.width = 1024;
    signCanvas.height = 256;
    const signContext = signCanvas.getContext("2d");

    signContext.fillStyle = "#17232c";
    signContext.fillRect(0, 0, 1024, 256);
    signContext.fillStyle = "#58e6a3";
    signContext.fillRect(0, 0, 18, 256);
    signContext.fillStyle = "#ffffff";
    signContext.font = "800 72px system-ui, sans-serif";
    signContext.textAlign = "center";
