      const inJunction = Math.abs(tramZ) < 12;
      const tramSignalState = {
        red: time >= 5 && time < 11,
        amber: false,
        green: !inJunction
      };

      const vehicleSignalState = {
        red: time < 5 || time >= 11,
        amber: false,
        green: !inJunction
      };

      const pedestrianSignalState = {
        red: !isScramblePhase(elapsed),
        amber: false,
        green: isScramblePhase(elapsed)
      };

      updateSignal(tramSignal, tramSignalState);
      updateSignal(vehicleSignals[0], vehicleSignalState);
      updateSignal(vehicleSignals[1], vehicleSignalState);
      updateSignal(vehicleSignals[2], vehicleSignalState);
      updateSignal(vehicleSignals[3], vehicleSignalState);

      pedestrianSignals.forEach((signal) => {
        updateSignal(signal, pedestrianSignalState);
      });

      // Pedestrian scramble: all four crossings open only while the tram is clear.
      const scrambleStart = 2;
      const scrambleDuration = 3.4;

      walkers.forEach((walker, index) => {
        let progress = 0;

        if (isScramblePhase(elapsed)) {
          progress = THREE.MathUtils.clamp(
            (elapsed - scrambleStart) / scrambleDuration,
            0,
            1
          );
        }

        const x = THREE.MathUtils.lerp(walker.start.x, walker.end.x, progress);
        const z = THREE.MathUtils.lerp(walker.start.z, walker.end.z, progress);

        walker.group.position.set(x, 0, z);
        walker.group.rotation.y = Math.atan2(
          walker.end.x - walker.start.x,
          walker.end.z - walker.start.z
        );

        const walking = progress > 0.02 && progress < 0.98;
        const stride = walking
          ? Math.sin(progress * Math.PI * 4) * 0.42
          : 0;

